style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/vpLJFOi.jpg") repeat center center fixed !important;
        background-size: 300px 300px !important; /* ajuste la taille des fibres */
        color: #e0e0e0 !important;
    }

    /* overlay léger */
    body::before {
        content: "";
        position: fixed;
        top: 0; left: 0;
        width: 100%; height: 100%;
        background: rgba(0, 0, 0, 0.3);
        pointer-events: none;
        z-index: 0;
    }

    /* tout le contenu au-dessus de l'overlay */
    * {
        position: relative;
        z-index: 1;
    }

    /* navbar, footer, blocs */
    .navbar, .footer, header, footer, .header {
        background: rgba(20,20,20,0.8) !important;
        border-radius: 12px !important;
        box-shadow: 0 0 10px rgba(0,0,0,0.6) !important;
    }

    /* liens racing */
    a {
        color: #00aced !important;
        transition: 0.3s;
    }
    a:hover {
        color: #ffcc00 !important;
    }

    /* boutons racing */
    button, .btn, input[type="submit"] {
        background: rgba(30,30,30,0.8) !important;
        color: #ffffff !important;
        border: 2px solid #444 !important;
        border-radius: 8px !important;
        transition: 0.3s;
    }
    button:hover, .btn:hover, input[type="submit"]:hover {
        background: rgba(50,50,50,0.9) !important;
        border-color: #00aced !important;
    }

    /* champs */
    input, textarea, select {
        background: rgba(25,25,25,0.7) !important;
        color: #e0e0e0 !important;
        border: 1px solid #555 !important;
        border-radius: 6px !important;
    }

    /* scrollbar */
    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-track {
        background: #111;
    }
    ::-webkit-scrollbar-thumb {
        background: #555;
        border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #00aced;
    }
}
